// React Native Bottom Navigation
// https://aboutreact.com/react-native-bottom-navigation/
import React, {useEffect, useState } from 'react';
import {
  TouchableOpacity,
  StyleSheet,
  Image,
  View,
  Text,
  Alert
} from 'react-native';
import { Colors } from '../../../Assets/Colors';
import { getIcon } from '../../../Assets/Icon';
import Buttons from '../../../Component/Button';
import TextInput from '../../../Component/TextInput';
import { Scale } from '../../../utils/size';
import { Routers } from '../../../utils/Routers';
import { JSONAxioPostFile } from '../../../utils/services/JsonService';
import { postURL } from '../../../utils/services/API';
import DeviceInfo, { getDeviceId, getSystemVersion, getBrand, getInstanceId } from 'react-native-device-info';
import uuid from 'react-native-uuid';
const Register = ({route, navigation, gotoLogin }) => {
  let [activeEye, setActiveEye] = useState(true);
  let [activeEyeConfirm, setActiveEyeConfirm] = useState(true);
  let [name, setName] = useState(null);
  let [email, setEmail] = useState(null);
  let [noHp, setNoHp] = useState(null);
  let [password, setPassword] = useState(null);
  let [confirmationPassword, setConfirmationPassword] = useState(null);
  let [referal, setReferal] = useState(null);
  let [loading, setLoading] = useState(false);

  let [nameError, setNameError] = useState(null);
  let [emailError, setEmailError] = useState(null);
  let [noHpError, setNoHpError] = useState(null);
  let [passwordError, setPasswordError] = useState(null);
  let [confirmationPasswordError, setConfirmationPasswordError] = useState(null);
  let [errorMessage, setErrorMessage] = useState(null);
  

  useEffect(() => {
    setReferal(route?.params?.dataQR)
  }, [route?.params]);
  
  const createTwoButtonAlert = (desc) =>
    Alert.alert('Yey !!!', desc, [
      {
        text: '',
        onPress: () => console.log('Cancel Pressed'),
        style: 'cancel',
      },
      {text: 'OK', onPress: () => gotoLogin(true)},
    ]);
  const onPressRegister =()=>{

    var isError = false;
    setNameError(null);
    setEmailError(null);
    setNoHpError(null);
    setPasswordError(null);
    setConfirmationPasswordError(null);
    setErrorMessage(null);

    if (name == '' || null == name) {
      setNameError("Harap masukan Nama");
      isError = true;
    }

    if (email == '' || null == email) {
      setEmailError("Harap masukan Nomor Hp");
      isError = true;
    }

    if (noHp == '' || null == noHp) {
      setNoHpError("Harap masukan Nomor Hp");
      isError = true;
    }

    if (password == '' || null == password) {
      setPasswordError("Harap masukan password");
      isError = true;
    }

    if (confirmationPassword == '' || null == confirmationPassword) {
      setConfirmationPasswordError("Harap masukan konfirmasi password");
      isError = true;
    }

    if (password != '' || null != password || confirmationPassword != '' || null != confirmationPassword) {

      if (password != confirmationPassword) {
        setConfirmationPasswordError("Konfirmasi password tidak sama");
        setPasswordError("Konfirmasi password tidak sama");
        isError = true;
      }
    }
    

    // if (!isError) {
      // navigation.navigate(Routers.OTP_SCREEN, {});
      onSubmitedRegister();
    // }
  }

  const onSubmitedRegister =()=>{

      setLoading(true);
      let brand = getBrand();
      let systemVersion = getSystemVersion();
      let idDevice = uuid.v4();
      var param = {
        nama :name,
        email :email ,
        pass :password,
        nomor_hp : noHp,
        idDevice :idDevice,
        referall:referal,
        os_version: brand+"_android_"+systemVersion,
        firebase_token: null
      }
      console.log("<<<param>>>");
      console.log(param);

      console.log("<<<param>>>");


      JSONAxioPostFile(postURL('api_registrasi_otp'), param, null)
      .then(respone => {
        gotoLogin(false);
        const response = respone.data;
        console.log("<<<response>>>");
        console.log(response)
        setLoading(false);
        if (response.statusCode > 1) {
          setErrorMessage(response.message);
          // gotoLogin(true);
        } else {
          navigation.navigate(Routers.OTP_SCREEN, {data:response, noHp : noHp, forgote: false});
          // createTwoButtonAlert(response.message);
        }
      })
      .catch(error => {
        gotoLogin(false);
        setLoading(false);
        const err = error.toJSON().message;
        setErrorMessage(err);
      });
  }
  return (
    <View>

      <TextInput
      
       onChange={value => {
        setName(value);
      }}
        // icon={} 
        value={name} 
        placeholder={'Nama'}
        //  onPress
        title={'Nama'}
        error={nameError}
      />

      <TextInput
      
        onChange={value => {
          setEmail(value);
        }}
        // icon={} 
        value={email} 
        placeholder={'Email'}
        //  onPress
        title={'Email'}
        error={emailError}
      />

      <TextInput
      
        onChange={value => {
          setNoHp(value);
        }}
        // icon={} 
        value={noHp} 
        placeholder={'Nomor Hp'}
        //  onPress
        title={'Nomor Hp'}
        error={noHpError}
        keyboardType={'numeric'}
      />

      <TextInput
      
        onChange={value => {
          setPassword(value);
        }}
        icon={activeEye ? 'ic_eye_close' : 'ic_eye_open'} 
        value={password} 
        placeholder={'Password'}
        onPress = {() => setActiveEye(!activeEye)}
        title={'Password'}
        secureTextEntry={activeEye}
        error={passwordError}
      />

      <TextInput
      
        onChange={value => {
          setConfirmationPassword(value);
        }}
        icon={activeEyeConfirm ? 'ic_eye_close' : 'ic_eye_open'} 
        value={confirmationPassword} 
        placeholder={'Konfirmasi Password'}
        onPress = {() => setActiveEyeConfirm(!activeEyeConfirm)}
        title={'Konfirmasi Password'}
        secureTextEntry={activeEyeConfirm}
        error={confirmationPasswordError}
      />

     

      <View style={{ flexDirection: 'row' }}>
        <View style={{ flex: 1 }}>
          <TextInput
          
            onChange={value => {
              setReferal(value);
            }}
            icon={'ic_scan'} 
            value={referal} 
            placeholder={'Referal'}
            onPress={() => console.log("")}//navigation.navigate(Routers.CAMERA_SCAN_QR_SCREEN, {page: Routers.REGISTER_SCREEN})} 
            
            title={'Referal'}
            error={null}
          />
        </View>
       
        {/* <View style={{ flex: 0.2 }}>
        <TouchableOpacity
        onPress={() => navigation.navigate(Routers.CAMERA_SCAN_QR_SCREEN, {})}>
          <Image
            style={{ height: Scale(30), width: Scale(30), position: 'absolute', bottom: Scale(15), backgroundColor: Colors.gray }}
            source={getIcon('ic_scan')} 
            resizeMode='contain'/>
            </TouchableOpacity>
        </View>
        */}
      </View>

      <View style={{justifyContent:'center', alignItems:'center'}}>
      <Text style={{color: Colors.red, alignItems: 'center', marginTop: Scale(16), fontSize: Scale(18)}}>{errorMessage}</Text>
      </View>

      <Buttons
        loading={loading}
        disabled={loading}
        style ={{marginTop : Scale(40), backgroundColor: loading ? Colors.greenWhite : Colors.primaryColor}}
        onPress={() => onPressRegister()}
        title={'Daftar'} />


    </View>
  );
}

const styles = StyleSheet.create({
  button: {
    alignItems: 'center',
    backgroundColor: '#DDDDDD',
    padding: 10,
    width: 300,
    marginTop: 16,
  },
});
export default Register;