import React, { useEffect, useState } from 'react';
import {
  TouchableOpacity,
  StyleSheet,
  View,
  Text,
  FlatList,
  SafeAreaView,
  Image
} from 'react-native';
import { Colors } from '../../../../Assets/Colors';
import { Metrics, Scale } from '../../../../utils/size';
import { getIcon } from '../../../../Assets/Icon';

const TabLayoutHub = ({ navigation, status, openStatus, openType, title, titleType, show }) => {
  let [itemTab, setanimateModal] = useState([{name: 'Pesanan Saya', flag: 'myCart', status : true}, {name: 'Menunggu Konfirmasi', flag: 'myPayment', status : false}, {name: 'Dikemas', flag: 'myPayment', status : false}, {name: 'Dikirim', flag: 'status', status : false}, {name: 'Selesai', flag: 'finish', status : false}, {name: 'Dibatalkan', flag: 'cancel', status : false}]);
  
  const updateTab = (index, type) => {
    var itemTabs = itemTab

    itemTabs.map((item, i) => {
      item.status = false;
    });

    itemTabs[index].status = true;
    status(itemTabs[index].flag)
    setanimateModal([...itemTabs])
    
  }
  return (
    <View>

      <View style={{ flexDirection: 'row', padding: Scale(16) }}>

        <View style={{ flex: 1, marginRight: Scale(14) }}>
          <TouchableOpacity
            onPress={() => openStatus()}>
            <View style={{ borderColor: Colors.primaryColorHub, borderWidth: Scale(1), borderRadius: Scale(8), padding: Scale(12), backgroundColor: Colors.white }}>
              <View style={{ flexDirection: 'row' }}>
                <View style={{ flex: 1.2 }}>
                  <Text style={{ color: Colors.primaryColorHub, fontSize: Scale(10) }}>{title}</Text>
                </View>
                <View style={{ flex: 0.1, justifyContent: 'center', marginRight: Scale(4) }}>
                  <Image
                    style={{ height: Scale(12), width: Scale(12), marginHorizontal: Scale(8), marginRight: Scale(10) }}
                    source={getIcon('ic_arrow_bottom')}
                    resizeMode='contain' />
                </View>
              </View>

            </View>
          </TouchableOpacity>
        </View>

        {show && <View style={{ flex: 1, marginRight: Scale(14) }}>
          <TouchableOpacity
            onPress={() => openType()}>
            <View style={{ borderColor: Colors.primaryColorHub, borderWidth: Scale(1), borderRadius: Scale(8), padding: Scale(12), backgroundColor: Colors.white }}>
              <View style={{ flexDirection: 'row' }}>
                <View style={{ flex: 1 }}>
                  <Text style={{ color: Colors.primaryColorHub, fontSize: Scale(10) }}>{titleType}</Text>
                </View>

                <View style={{ flex: 0.1, justifyContent: 'center', marginRight: Scale(8) }}>
                  <Image
                    style={{ height: Scale(12), width: Scale(12), marginHorizontal: Scale(8), marginRight: Scale(10) }}
                    source={getIcon('ic_arrow_bottom')}
                    resizeMode='contain' />
                </View>
              </View>

            </View>
          </TouchableOpacity>
        </View>}

      </View>

      

    
    </View>
  );
}

const styles = StyleSheet.create({
  button: {
    alignItems: 'center',
    backgroundColor: '#DDDDDD',
    padding: 10,
    width: 300,
    marginTop: 16,
  },
  text60012: { color: Colors.black,  fontSize: Scale(14) },
});
export default TabLayoutHub;