// React Native Bottom Navigation
// https://aboutreact.com/react-native-bottom-navigation/
import React, {useEffect,  useState }  from 'react';
import {
  TouchableOpacity,
  StyleSheet,
  Image,
  View,
  Text,
  FlatList
} from 'react-native';
import { Colors } from '../../../Assets/Colors';
import { getIcon } from '../../../Assets/Icon';
import Buttons from '../../../Component/Button';
import TextInput from '../../../Component/TextInput';
import { Metrics, Scale } from '../../../utils/size';
import Account from '../Profile/Account';
import { Routers } from '../../../utils/Routers';
import Toolbar from '../../../Component/Toolbar';
import { getData, removeData } from '../../../utils/Storage';
import { Constants } from '../../../utils/Constans';
import { JSONAxioGet, JSONAxioPost } from '../../../utils/services/JsonService';
import { getURL, getURLHub, postURL } from '../../../utils/services/API';
import PopUp from '../../../Component/popUp';
import ModalStatusReadyToSend from '../../../Component/ModalStatusReadyToSend';
import Loading from '../../../Component/loading';

const Pencairan = ({ route, navigation }) => {

  let [switchAccount, setswitchAccount] = useState(false);
  let [dataTabFlag, setDataTabFlag] = useState([]);
  let [showStatus, setShowStatus] = useState(false);
  
  let [hub, setHub] = useState(null);
  let [dataCoint, setDataCoint] = useState({ focoCoint: "0", focoPoint: "0", saldo: "0", totalReferal: 0 });
  let [loading, setLoading] = useState(false);
  let [contentWarning, setContentWarning] = useState(null);
  let [warning, setWarning] = useState(false);
  let [tokens, setTokens] = useState(false);
  
  let [setTabFlag, selectSetTabFlag] = useState(null);
  let [setTo, selectSetTo] = useState(null);
  let [setNoRek, selectSetNoRek] = useState(null)
  let [setNameRek, selectSetNameRek] = useState(null);
  let [setAmount, selectSetAmount] = useState(null);

  useEffect(() => {
    getData(Constants.SESSION_HUB).then(res => {
      
      setswitchAccount(res ? true :  false);
 


      getData(Constants.SESSION_USER_PROFILE).then(res => {
        var params = {
          userid: res ? res.result.hp : '0'
        }
        setTokens(res.result.token)
        getPoint(params, res.result.token);
        getSelectTypeWalet(res.result.token);
      })
    });
    
  }, []);


  
  const goBack =(item)=>{
    navigation.goBack()
  }


  const getPoint = (params, token) => {
    setLoading(true);
    JSONAxioGet(getURL('get-coint', params), null, token)
      .then(respone => {
        const response = respone.data;
        setLoading(false);

        if (response.statusCode == 1) {
          setDataCoint(response.result);
        } else {
          cekError(response.statusCode, response.message)
        }
      })
      .catch(error => {
        setLoading(false);
        console.log("error")
        console.log(error)
      });
  }

  const getSelectTypeWalet = (token) => {
    setLoading(true);
    JSONAxioGet(getURLHub('api_select_tipe_wallet'), null, token)
      .then(respone => {
        const response = respone.data;
        setLoading(false);
        if (response.statusCode == 1) {
          setDataTabFlag(response.result);
        } else {
          cekError(response.statusCode, response.message)
        }
      })
      .catch(error => {
        setLoading(false);
      });
  }

  const slectItemWalet = (data) => {
    selectSetTabFlag(data);
    setShowStatus(false)
  }

  const cekError = (statusCode, errorMessage) => {
    setWarning(true);
    if (statusCode == 401 || statusCode == 400) {
      setContentWarning({
        title: "Oooops !!",
        desc: errorMessage,
        titleButton: "Login Kembali",
        statusCode: statusCode
      })
    }
    else if (statusCode == 1) {
      setContentWarning({
        title: "Yeey !!",
        desc: errorMessage,
        titleButton: "OK",
        statusCode: statusCode
      })
    }
    else {
      setLoading(false);
      setContentWarning({
        title: "Oooops !!",
        desc: errorMessage,
        titleButton: "OK",
        statusCode: statusCode
      })
    }
  }

  const actionButton = () => {
    setWarning(false);
    setContentWarning(null)
    if (contentWarning?.statusCode == 401 || contentWarning?.statusCode == 400) {
      removeData(Constants.SESSION_USER_PROFILE).then(() => {
        removeData(Constants.SESSION_HUB).then(() => {
          navigation.reset({ index: 0, routes: [{ name: "LoginStack" }] });
        });
      });
    }

  }

  const onPressAjukan = () => {

    setLoading(true);
    var param ={
      "bank": setTo,
      "namaRekening": setNameRek,
      "nominal": setAmount,
      "nomorRekening": setNoRek,
      "tipe_wallet": setTabFlag?.value
    }
    JSONAxioPost(postURL('api_saldo_member', null), param, tokens)
    .then(respone => {
      const response = respone?.data;

      setLoading(false);
      if (response?.statusCode == 1) {
        navigation.navigate(Routers.SUCCESS_SCREEN, {title: 'Pencairan Diproses', desc: response?.message, titleButton:'Kembali'})
      } else {
        cekError(response.statusCode,  response.message);

      }
    })
    .catch(error => {
      setLoading(false);
      cekError(2,  null);

    });

  }

  return (
    <View style={{flex:1, backgroundColor: Colors.white}}>

      <Toolbar
        switchAccount={switchAccount}
        onPress={goBack}
        title={'Pencairan Rewords'} />

      
      
      <FlatList
        style={{ marginTop: Scale(20) }}
        showsVerticalScrollIndicator={false}
        showsHorizontalScrollIndicator={false}
        data={[""]}
        renderItem={({ item, index }) => (
          <View>
            <Account
              key={0}
              onPresSwitch={() => { console.log("") }}
              dataCoint={dataCoint}
              switchAccount={switchAccount}
              navigation={navigation} />

            <TextInput
              // onChange={value => {
              //   setEmail(value);
              // }}
              icon={"ic_arrow_bottom"} 
              value={setTabFlag?.name} 
              placeholder={'Sumber Pencairan Saldo'}
              onPress ={() => {
                setShowStatus(true)
               }}
              title={'Sumber Pencairan Saldo'}
            // error={emailError}
            editable={false}
            />

            <TextInput
              onChange={value => {
                selectSetTo(value);
              }}
              // icon={} 
              // value={} 
              placeholder={'Tujuan Pencairan'}
              //  onPres
              title={'Tujuan Pencairan'}
            // error={emailError}
            // editable={!loading}
            />

            <TextInput
              onChange={value => {
                selectSetNoRek(value);
              }}
              // icon={} 
              // value={} 
              placeholder={'Nomor Rekening'}
              //  onPres
              title={'Nomor Rekening'}
            // error={emailError}
            // editable={!loading}
              keyboardType={'numeric'}
            />

            <TextInput
              onChange={value => {
                selectSetNameRek(value);
              }}
              // icon={} 
              // value={} 
              placeholder={'Nama Rekening'}
              //  onPres
              title={'Nama Rekening'}
            // error={emailError}
            // editable={!loading}
            />

            <TextInput
              onChange={value => {
                selectSetAmount(value);
              }}
              // icon={} 
              // value={} 
              placeholder={'Masukan Jumlah Pencairan'}
              //  onPres
              title={'Masukan Jumlah Pencairan'}
            // error={emailError}
            // editable={!loading}
              keyboardType={'numeric'}
            />

            <Text style={{ margin: Scale(16), color: Colors.txtGray }}>Nilai minimal Rp. 25.000 atau 25.000 poin atau 25.000 coin </Text>

            <Buttons
              loading={loading}
              disabled={loading}
              style={{margin: Scale(16), marginTop: Scale(40), backgroundColor: loading ? Colors.greenWhite : Colors.primaryColorHub }}
              onPress={() => onPressAjukan()}
              title={'Ajukan Pencairan'} />
          </View>
        )
        }
      />


      <ModalStatusReadyToSend
        isHubSend={route.params?.isHubSend}
        dataPencairanHub={dataTabFlag}
        isPencairanHub={true}
        readySend={true}
        onPresStatus={(item) => slectItemWalet(item)}
        onClose={() => setShowStatus(false)}
        ShowStatus={showStatus} />

      <PopUp
        visible={warning}
        onPressButton={() => {actionButton()}}
        title={contentWarning?.title}
        desc={contentWarning?.desc}
        titleButton={contentWarning?.titleButton} />

      <Loading
        visible={loading} />

    </View>
  );
}

const styles = StyleSheet.create({
  button: {
    alignItems: 'center',
    backgroundColor: '#DDDDDD',
    padding: 10,
    width: 300,
    marginTop: 16,
  },
  text400: { color: Colors.black, fontWeight: '400', fontSize: Scale(14) },
  text600: { color: Colors.black, fontWeight: '600', fontSize: Scale(14) },
  text40012: { color: Colors.black, fontWeight: '400', fontSize: Scale(12) },
});
export default Pencairan;