import React, {useEffect, useState } from 'react';
import {
  StyleSheet,
  View,
  Text,
  Image,
  TouchableOpacity,
  ImageBackground,
  Dimensions 
} from 'react-native';
import
FontAwesome
  from 'react-native-vector-icons/FontAwesome5';
import { Metrics, Scale } from '../../../../utils/size';
import { Colors } from '../../../../Assets/Colors';
import { getIcon } from '../../../../Assets/Icon';
import QRCode from 'react-native-qrcode-svg';
import { Routers } from '../../../../utils/Routers';
import { Constants } from '../../../../utils/Constans';
import { getData, removeData, storeData } from '../../../../utils/Storage';
import { currency } from '../../../../utils/General';
import ModalChooseUser from '../../../../Component/ModalChooseUser';

const deviceWidth = Dimensions.get('screen').width;

const Account = ({ navigation, changeButton, switchAccount, dataCoint, onPresSwitch }) => {
  let [login, setLogin] = useState(null);
  let [otherUser, setOtherUser] = useState([]);
  let [akun, setAkun] = useState("-");
  
  let [chooseLogin, setChooseLogin] = useState([
    {
      "id": "",
      "name": "",
      "userRole": "USER"
  }]);
  let [showModal, setShowModal] = useState(false);
  // let [switchAccount, setSwitchAccount] = useState(false);
  const onPressSwitch =()=>{
    setShowModal(!showModal)
    // onPresSwitch();
    getData(Constants.SESSION_USER_PROFILE).then(res => {
      var chooseLogins = res.result.otherUser;
    if (chooseLogin.length == 1){
      setChooseLogin([...chooseLogin,...chooseLogins])
    }
      
      setLogin(res.result);
    })
    
  }

  const onPressChooseSwitch =(item)=>{

    getData(Constants.SESSION_HUB).then(res => {
      
      if (item.userRole === "USER") {
        // setSwitchAccount(false);
        removeData(Constants.SESSION_HUB).then(() => {
          navigation.reset({ index: 0, routes: [{ name: Routers.MAIN_PAGE }] });
        });
      } else {
        // setSwitchAccount(true);
        storeData(Constants.SESSION_HUB, JSON.stringify(item));
        navigation.reset({ index: 0, routes: [{ name: Routers.MAIN_PAGE }] });
      }

    });

  }

  useEffect(() => {
    getData(Constants.SESSION_USER_PROFILE).then(res => {
      setOtherUser(res.result.otherUser)
      setLogin(res.result);
    })

     getData(Constants.SESSION_HUB).then(res => {
      if (res){
        
        setAkun(JSON.parse(res).userRole)
      } else {
        setAkun("USER")
      }
     })

 
    

      
  }, []);


  return (

    
    <View>
      <Image
        style={{ height: Scale(200), width: Metrics.screenWidth-32, position:'absolute', alignSelf:'center' }}
        source={getIcon(switchAccount ? 'bg_card_blue' : 'bg_card_orange')}
        resizeMode='contain' />
      <View style={styles.container}>

        <View style={styles.containerRow}>
          <Image
            style={styles.imgRow}
            source={getIcon('ic_user')}
            resizeMode='contain' />

          <View
            style={styles.viewCenter}>
            <View style={styles.viewCenterPadding}>
              <Text style={[styles.text600, { color: Colors.white}]}>{login ? (login.name ? login.name : "-") : "-"}</Text>
              <Text style={[styles.text600, { color: Colors.white}]}>{login ? (login.accountType || login.accountType != '' ? login.accountType : '-') : "-"}</Text>
            </View>
          </View>
          
          {otherUser.length !==0 && <View style={{flex:0.3, alignItems:'center', justifyContent: 'center'}}>
            <TouchableOpacity
            onPress={() => onPressSwitch()}>
              <View style={{alignItems:'center', justifyContent: 'center'}}>
                <Image
                  style={{ height: Scale(20), width: Scale(20) }}
                  source={getIcon('ic_switch')}
                  resizeMode='contain' />

                <Text style={[styles.text60012, { color: Colors.white, fontSize: Scale(8) }]}>{'Ubah Akun'}</Text>

               
              </View>
            </TouchableOpacity>
            
          </View>}

        </View>

        <View style={{ flex: 1, flexDirection: 'row' }}>
          <View style={{ flex: 1, alignItems:'flex-end' }}>
          {/* navigation.navigate(Routers.CAMERA_SCAN_QR_SCREEN, {}) */}
            <TouchableOpacity
              onPress={() => console.log("")}> 
              <View style={{ marginTop: Scale(18), marginRight: Scale(20) }}>
                <Image
                  style={{ height: Scale(20), width: Scale(20), marginHorizontal: Scale(8) }}
                  source={getIcon('ic_scan_white')}
                  resizeMode='contain' />
              </View>
            </TouchableOpacity>

          </View>
          {login?.kodeReferal != "" &&<View style={{ flex: 0.2 }}>
            <TouchableOpacity
              onPress={() => navigation.navigate(Routers.KODE_REFERAL_SCREEN, {})}>
              <View style={{ marginTop: Scale(18) }}>
                <QRCode
                  size={Scale(20)}
                  value="tester"
                />
              </View>
            </TouchableOpacity>
          </View>}
        </View>

        <View style={{flexDirection:'row', paddingHorizontal: Scale(8), position: 'absolute', bottom: Scale(68), alignSelf: 'center'}}>
            <View style = {{flex:1}}>
            <Text style={[styles.text40012, { color: Colors.white}]}>{'Akun : ' + akun} </Text>
            {/* {login ? (login.accountType || login.accountType != '' ? login.accountType : '-') : "-"}</Text> */}
            </View>
            <View style = {{flex:1, alignItems:'flex-end'}}>
            <Text style={[styles.text40012, { color: Colors.white}]}>{'Total Referal : '} {dataCoint.totalReferal}</Text>
            </View>
        </View>

        <View style={[styles.viewRowSaldo, {backgroundColor: switchAccount ? Colors.gray8a: Colors.green004}]}>
          <View style={{ flex: 1.5 }}>

            <View>
              <Text style={[styles.text60012, {color: Colors.white}]}>{'Saldo'}</Text>
              <Text style={[styles.text40012, { alignItems: 'center', color: Colors.white }]}> 
              {/* {<FontAwesome
                name={'wallet'}
                size={15}
                color={Colors.primaryColor}
              />} */}
              {"Rp "+currency( dataCoint.saldo, "")}
              </Text>
            </View>

          </View>

          <View style={{ flex: 1.5, marginHorizontal: Scale(10) }}>
            <Text style={[styles.text60012, {color: Colors.white}]}>{'Coin'}</Text>
            <Text style={[styles.text40012, { alignItems: 'center', color: Colors.white }]}> 
            {/* {<FontAwesome
              name={'coins'}
              size={15}
              color={Colors.primaryColor}
            />} */}
            {currency(dataCoint.focoCoint,"")}
            </Text>
          </View>



          <View style={{ flex: 1 }}>
            <Text style={[styles.text60012, {color: Colors.white}]}>{'Poin'}</Text>
            <Text style={[styles.text40012, { alignItems: 'center', color: Colors.white }]}> 
            {/* {<FontAwesome
              name={'hand-holding-usd'}
              size={15}
              color={Colors.primaryColor}
            />} */}
            {currency(dataCoint.focoPoint,"")}
            </Text>
          </View>

        </View>
      </View>

      <ModalChooseUser
      itemTab={chooseLogin}
      onClose={() => setShowModal(false)}
      ShowStatus={showModal}
      onPressChooseSwitch= {(items) => {onPressChooseSwitch(items)}}/>
    </View>
   
  );
}

const styles = StyleSheet.create({
  container: { height: Scale(185), marginTop: Scale(8), padding: Scale(16) },
  containerRow: { flexDirection: 'row', paddingHorizontal: Scale(22) },
  imgRow: { height: Scale(40), width: Scale(40) },
  viewCenter: { flex: 1,},
  viewCenterPadding: { paddingLeft: Scale(16), paddingRight: Scale(16) },
  text600: { color: Colors.black, fontWeight: '600', fontSize: Scale(14) },
  text60012: { color: Colors.black, fontWeight: '600', fontSize: Scale(12) },
  text40012: { color: Colors.black, fontWeight: '400', fontSize: Scale(12) },
  text40014: { color: Colors.black, fontWeight: '400', fontSize: Scale(14) },
  viewRowSaldo: { flexDirection: 'row', width: Metrics.screenWidth-32,alignSelf:'center', height: Scale(60), backgroundColor: Colors.green004, marginVertical: Scale(0), borderRadius: Scale(10), padding: Scale(10), position:'absolute', bottom:0 },
  buttonScan: {
    borderWidth: 2,
    borderRadius: 10,
    borderColor: '#004C27',
    paddingTop: 5,
    paddingRight: 25,
    paddingBottom: 5,
    paddingLeft: 25,
    marginTop: 20
},
buttonScan2: {
    width: 100,
    height: 100,
},
});
export default Account;