// React Native Bottom Navigation
// https://aboutreact.com/react-native-bottom-navigation/
import React, {useEffect, useState }  from 'react';
import {
  TouchableOpacity,
  StyleSheet,
  Image,
  View,
  Text,
  FlatList
} from 'react-native';
import { Colors } from '../../../../Assets/Colors';
import { getIcon } from '../../../../Assets/Icon';
import Buttons from '../../../../Component/Button';
import TextInput from '../../../../Component/TextInput';
import { Metrics, Scale } from '../../../../utils/size';
import Account from '../../Profile/Account';
import { Routers } from '../../../../utils/Routers';
import Toolbar from '../../../../Component/Toolbar';
import * as Progress from 'react-native-progress';
import { getData } from '../../../../utils/Storage';
import { Constants } from '../../../../utils/Constans';
import { JSONAxioGet } from '../../../../utils/services/JsonService';
import { getURL } from '../../../../utils/services/API';
import { currency } from '../../../../utils/General';

const RewardsComisionDetil = ({ route, navigation }) => {
  let [switchAccount, setswitchAccount] = useState(false);
  let [loading, setLoading] = useState(false);
  let [token, setToken] = useState(null);
  let [search, setSearch] = useState("");
  let[totalPage, setTotalPage] = useState(1);
  let[currentPage, setCurrentPage] = useState(1);
  let [contentWarning, setContentWarning] = useState(null);
  let [warning, setWarning] = useState(false);
  let [dataCoint, setDataCoint] = useState({focoCoint: "0", focoPoint: "0", saldo: "0", totalReferal: 0});
  useEffect(() => {
    getData(Constants.SESSION_HUB).then(res => {
     
      setswitchAccount(res ? true :  false);
      
      getData(Constants.SESSION_USER_PROFILE).then(res => {
        var params = {
          userid: res ? res.result.hp : '0'
        }
        setToken(res.result.token);
        getPoints(params, res.result.token);
        getPoint("",res.result.token, 1)
      })
    });
    
  }, []);
  let [listItem, setlistItem] = useState([]);
  

  const goBack =(item)=>{
    navigation.goBack()
  }

  const refresh = () => {
    setlistItem([])
    listItem = []
    console.log("Length >>>>> ", listItem.length)
    getData(Constants.SESSION_USER_PROFILE).then(res => {
      var params = {
        userid: res ? res.result.hp : '0'
      }
      setToken(res.result.token);
      getPoints(params, res.result.token);
      getPoint("",res.result.token, 1)
    })
  }

  const handleLoadMore = () => {
    if (currentPage < totalPage) {
      console.log("Load More ", currentPage, " totalPage ", totalPage )
      
      getData(Constants.SESSION_USER_PROFILE).then(res => {
        
        setToken(res.result.token);
        getPoint("",res.result.token, (currentPage + 1))
      })
    }
  };

  const getPoint = (params, token, currentPage) => {
    setLoading(true);
    var param = {
      search : search,
      pagination: currentPage
    }

    var url ="";

    if (route.params?.item.title === "Poin"){
      url = "api_history_poin"
    } else if (route.params?.item.title === "Coin"){
      url = "api_history_coin"
    }
    
    else if (route.params?.item.title === "Saldo"){
      url = "api_history_saldo"
    }

    

    JSONAxioGet(getURL(url, param), null, token)
      .then(respone => {
        const response = respone.data;
        setLoading(false);

        if (response.statusCode == 1) {
          setlistItem([...listItem, ...response.result])
          // setlistItem(response.result)
          setTotalPage(response.totalPage)
          setCurrentPage(currentPage)
        } else {
          // cekError(response.statusCode, response.message)
        }
      })
      .catch(error => {
        setLoading(false);
        console.log("errorssss")
        console.log(error)
      });
  }

  const getPoints = (params, token) => {
    setLoading(true);
    JSONAxioGet(getURL('get-coint', params), null, token)
      .then(respone => {
        const response = respone.data;
        setLoading(false);

        if (response.statusCode == 1) {
          setDataCoint(response.result);
         
        } else {
          cekError(response.statusCode, response.message)
        }
      })
      .catch(error => {
        setLoading(false);
        console.log("error")
        console.log(error)
      });
  }

  const cekError = (statusCode, errorMessage) => {
    setWarning(true);
    if (statusCode == 401 || statusCode == 400) {
      setContentWarning({
        title: "Oooops !!",
        desc: errorMessage,
        titleButton: "Login Kembali",
        statusCode: statusCode
      })
    } else if (statusCode == 1) {
      setContentWarning({
        title: "Yeyy !!",
        desc: errorMessage,
        titleButton: "OK",
        statusCode: statusCode
      })
    }
    else {
      setContentWarning({
        title: "Oooops !!",
        desc: errorMessage,
        titleButton: "OK",
        statusCode: statusCode
      })
    }
  }

  return (
    <View style={{flex:1, backgroundColor: Colors.gray}}>

      <Toolbar
        switchAccount={switchAccount}
        styleContainer={{backgroundColor: Colors.white}}
        onPress={goBack}
        title={route.params?.item.title} />

      <Account
      dataCoint={dataCoint}
        switchAccount={switchAccount}
        navigation={navigation} />
      
      {/* <Text style={[styles.text40012, { marginHorizontal: Scale(16), marginVertical: Scale(16), fontSize: Scale(16), color: Colors.black }]}>{'Riwayat Penjualan'}</Text> */}
      <View style={{ backgroundColor:Colors.white, marginTop: Scale(4) }}>
      {<View style={{ backgroundColor: Colors.white, flexDirection:'row' }}>
          
          <View style={{ flex: 1, paddingVertical: Scale(8)}}>
            <TextInput
              onChange={ (search) => { setSearch(search)}}
              icon={'ic_search'}
              value={search} 
              placeholder={'Search'}
              onPress={() => getPoint("", token)}
              title={''}
              error={null}
            />
          </View>

          {<View style={{flex:0.1, alignItems:'center', justifyContent:'center', paddingRight: Scale(16)}}>

            <Image
              style={{ height: Scale(30), width: Scale(30), marginHorizontal: Scale(8), tintColor: switchAccount ? Colors.primaryColorHub : Colors.primaryColor }}
              source={getIcon('ic_filter')}
              resizeMode='contain' />

          </View>}
          
          

        </View>}
          </View>

      <FlatList
        showsVerticalScrollIndicator={false}
        showsHorizontalScrollIndicator={false}
        refreshing={loading}
        onRefresh={() => {refresh()}}
        data={listItem}
        onEndReachedThreshold={0.4}
        onEndReached={handleLoadMore.bind(this)}
        renderItem={({ item, index }) => (
          <TouchableOpacity
          >

            <View style ={{borderColor: Colors.white, borderWidth: Scale(1), borderRadius: Scale(8), marginHorizontal: Scale(16), marginVertical: Scale(8), padding: Scale(16), backgroundColor:Colors.white}}>
              <View style={{ flexDirection: 'row' }}>

                <View style={{ flex: 0.2, marginLeft: Scale(20), justifyContent: 'center'}}>
                  <Text style={[styles.text40012, { marginVertical: Scale(6), color: item.tipeTransaksi === "IN" ? Colors.primaryColorHub : Colors.red, fontWeight: 'bold' }]}>{item.transaction_type}</Text>
                </View>

                <View style={{ flex: 1, marginLeft: Scale(20) }}>
                  <View style={{ flexDirection: 'row' }}>
                    <View style={{ flex: 0.8 }}><Text style={[styles.text40012, { marginVertical: Scale(6), fontWeight:'bold' }]}>{(route.params?.item.title === "Coin" ? currency(item.coin.toString(),"") : (route.params?.item.title === "Poin" ? (currency( item.poin.toString(),"")  + " "+ route.params?.item.title) : currency(item.saldo.toString())))}</Text></View>
                    <View style={{ flex: 1, justifyContent:'flex-end', alignItems: 'flex-end' }}>
                      <Text style={[styles.text40012, { marginVertical: Scale(6), color: Colors.primaryColorHub, fontWeight:'bold' }]}>{item.transaction_id}</Text>
                    </View>
                  </View>

                  <View style={{ flexDirection: 'row' }}>
                    <View style={{ flex: 0.8 }}><Text style={[styles.text40012, {color: Colors.gray8a, fontWeight : 'bold'}]}>{route.params?.item.title === "Saldo" ? item.desc: item.user}</Text></View>

                  </View>

                  <View style={{ flexDirection: 'row' }}>
                    <View style={{ flex: 1 }}><Text style={[styles.text40012, {marginVertical: Scale(6)}]}>{item.transaction_date}</Text></View>
                  </View>

                  

                </View>


              </View>

           

            </View>
          </TouchableOpacity>
        )
        }
      />





    </View>
  );
}

const styles = StyleSheet.create({
  button: {
    alignItems: 'center',
    backgroundColor: '#DDDDDD',
    padding: 10,
    width: 300,
    marginTop: 16,
  },
  text400: { color: Colors.black, fontWeight: '400', fontSize: Scale(14) },
  text600: { color: Colors.black, fontWeight: '600', fontSize: Scale(14) },
  text40012: { color: Colors.black, fontWeight: '400', fontSize: Scale(12) },
});
export default RewardsComisionDetil;