
const currency = (angka, prefix) => {
    var coma = (angka == undefined) ? "0" :angka.toString().split('.');
    var number_string = ((angka == undefined) ? "0" : (coma[0] != 0 ? coma[0] : angka.toString().replace(/[^,\d]/g, '').toString())),
      split = number_string.split(','),
      sisa = split[0].length % 3,
      rupiah = split[0].substr(0, sisa),
      ribuan = split[0].substr(sisa).match(/\d{3}/gi);
  
    // tambahkan titik jika yang di input sudah menjadi angka ribuan
    if (ribuan) {
      separator = sisa ? '.' : '';
      rupiah += separator + ribuan.join('.');
    }
  
    rupiah = split[1] != undefined ? rupiah + ',' + split[1] : rupiah;
    var result = (prefix == undefined ? rupiah : rupiah ? '' + rupiah : '');
    return (coma[1] == undefined || coma[0] == 0)? result : (result+"."+coma[1]);
}



export {currency}