import React, { useEffect, useState } from 'react';
import {
  TouchableOpacity,
  StyleSheet,
  View,
  Text,
  Image,
  ScrollView,
  SafeAreaView
} from 'react-native';
import { Colors } from '../../../../Assets/Colors';
import { getIcon } from '../../../../Assets/Icon';
import Toolbar from '../../../../Component/Toolbar';
import { Scale } from '../../../../utils/size';
import
FontAwesome
  from 'react-native-vector-icons/FontAwesome5';
import Buttons from '../../../../Component/Button';
import { Routers } from '../../../../utils/Routers';
import ItemOrder from './ItemOrder';
import AddModal from '../../../../Component/AddModal';
import ModalConfirmationOrder from '../../../../Component/ModalConfirmationOrder';
import ModalConformationSendHub from '../../../../Component/ModalConformationSendHub';
import Loading from '../../../../Component/loading';
import PopUp from '../../../../Component/popUp';
import { removeData } from '../../../../utils/Storage';
import { Constants } from '../../../../utils/Constans';

const DetilOrderHubScreen = ({route, navigation }) => {
  const [showModalConfirm, setShowModalConfirm] = useState(false);
  const [dataDetil, setDataDetil] = useState(route.params?.data);

  let [sendByState, setSendByState] = useState(
    { name: 'Dikirim Oleh Hub', icon: 'ic_send_hub', height: Scale(20), width: Scale(50) });

  let [paymentMethode, setPaymentMethode] = useState(
    { name: 'Cash On Delivery (COD)', category: null, icon: 'ic_cod', height: Scale(20), width: Scale(40) });

  let [voucher, setVoucher] = useState(
    { name: 'Pilih Voucher', desc: 'S&K Berlaku Berlaku 25-03-2023', icon: 'ic_foco_voucher', height: Scale(20), width: Scale(20) });

  let [addres, setAddress] = useState(
    { name: 'Kota Tangerang', desc: 'Jl Mushola alihsan RT 02 RW 03 Pakulonan Serpong Utara Tangerang Selatan Banten' });

  let [loading, setLoading] = useState(false);
  let [contentWarning, setContentWarning] = useState(null);
  let [warning, setWarning] = useState(false);


    useEffect(() => {
      if (route.params?.sendBy) {
        setSendByState(route.params?.sendBy);
      }

      if (route.params?.paymentMethode) {
        setPaymentMethode(route.params?.paymentMethode);
      }

      if (route.params?.voucher) {
        setVoucher(route.params?.voucher);
      }

      if (route.params?.address) {
        setAddress(route.params?.address);
      }
    }, [route.params]);

  const openSendBy =()=>{
    navigation.navigate(Routers.METODE_SEND, {})
  }

  const openPaymentMethode =()=>{
    navigation.navigate(Routers.PAYMENT_METODE, {})
  }

  const openVoucher =()=>{
    navigation.navigate( Routers.VOUCHER_SCREEN, {})
  }

  const openAddress =()=>{
    navigation.navigate( Routers.SEARCH_ADDRESS_SCREEN, {})
  }
  

  const goBack =(item)=>{
    navigation.goBack()
  }

  const onPresHubSendConfirm = (value) => {
    setShowModalConfirm(!showModalConfirm)
    if (value) {
      navigation.navigate(Routers.SUCCESS_SCREEN, { title: 'Pengiriman Diproses', desc: 'Terimakasih , Pengiriman produk kamu telah berhasil dan sedang di proses , Klik tombol dibawah untuk cek status pengiriman kamu', titleButton: 'Kirim Pesanan Lainnya' })
    }
  }

  const cekError = (statusCode, errorMessage) => {
    setWarning(true);
    if (statusCode == 401 || statusCode == 400) {
        setContentWarning({
          title: "Oooops !!",
          desc: errorMessage,
          titleButton: "Login Kembali",
          statusCode: statusCode
        })
    } else if (statusCode == 1) {
      setContentWarning({
        title: "Yeyy !!",
        desc: errorMessage,
        titleButton: "OK",
        statusCode: statusCode
      })
    }
    else {
      setContentWarning({
        title: "Oooops !!",
        desc: errorMessage,
        titleButton: "OK",
        statusCode: statusCode
      })
    }
  }

  const actionButton = (statusCode) => {
    setWarning(false);
    setContentWarning(null)
    if (contentWarning?.statusCode == 401 || contentWarning?.statusCode == 400) {
      removeData(Constants.SESSION_USER_PROFILE).then(() => {
        removeData(Constants.SESSION_HUB).then(() => {
          navigation.reset({ index: 0, routes: [{ name: Routers.MAIN_PAGE }] });
        });
      });
    } 
    
  }
  return (
    <SafeAreaView style={{ flex: 1, }}>
      <View style={{ flex: 1, backgroundColor: Colors.white }}>

        <Toolbar
        switchAccount={true}
        onPress={goBack}
        title={'Detil Pesanan'} />

        <ScrollView>
          <View style={{ flex: 1 }}>

            <View style={{ paddingHorizontal: Scale(16), paddingVertical: Scale(16), borderColor: Colors.gray, borderBottomWidth: Scale(2) }}>

              <View style={{ flexDirection: 'row' }}>
                <View style={{ flex: 1 }}>
                  <Text style={{ color: Colors.black, fontWeight: '600' }}>{"Nomor Pesanan"}  </Text>
                </View>

              </View>

              <View style={{ paddingVertical: Scale(4) }}>
                <Text style={{ color: Colors.black, fontWeight: '300' }}>{dataDetil?.transaction_id}</Text>
              </View>

            </View>

            <View style={{ paddingHorizontal: Scale(16), paddingVertical: Scale(16), borderColor: Colors.gray, borderBottomWidth: Scale(2) }}>

              <View style={{ flexDirection: 'row' }}>
                <View style={{ flex: 1 }}>
                  <Text style={{ color: Colors.black, fontWeight: '600' }}>{"Tanggal Pesanan"}  </Text>
                </View>

              </View>

              <View style={{ paddingVertical: Scale(4) }}>
                <Text style={{ color: Colors.black, fontWeight: '300' }}>{dataDetil?.transaction_date}</Text>
              </View>

            </View>

            <View style={{ paddingHorizontal: Scale(16), paddingVertical: Scale(16), borderColor: Colors.gray, borderBottomWidth: Scale(2) }}>

              <View style={{ flexDirection: 'row' }}>
                <View style={{ flex: 1 }}>
                  <Text style={{ color: Colors.black, fontWeight: '600' }}>{"Jam Kirim"}  </Text>
                </View>

              </View>

              <View style={{ paddingVertical: Scale(4) }}>
                <Text style={{ color: Colors.black, fontWeight: '300' }}>{dataDetil?.delivery_hours}</Text>
              </View>

            </View>

            <View style={{ paddingHorizontal: Scale(16), paddingVertical: Scale(16), borderColor: Colors.gray, borderBottomWidth: Scale(2) }}>

              <View style={{ flexDirection: 'row' }}>
                <View style={{ flex: 1 }}>
                  <Text style={{ color: Colors.black, fontWeight: '600' }}>{"Alamat Pengiriman"}  {<FontAwesome
                    name={'map-marker-alt'}
                    size={15}
                    color={Colors.primaryColorHub}
                  />}</Text>
                </View>

              </View>

              <View style={{ paddingVertical: Scale(16) }}>
                <Text style={{ color: Colors.black, fontWeight: '300' }}>{dataDetil?.senders_address}</Text>
              </View>

            </View>


            {dataDetil?.product.map((item, i) =>
            (<ItemOrder
              data={item}
              onPress={() => console.log('')}/>)
            )}
            

            <View style={{ paddingHorizontal: Scale(16), paddingVertical: Scale(16), borderColor: Colors.gray, borderBottomWidth: Scale(2) }}>
              
              <View style={{}}>
                <View style={{ flexDirection: 'row' }}>
                  <View style={{ flex: 1 }}>
                    <Text style={{ color: Colors.black, fontWeight: '600' }}>{"Metode Pengiriman"}</Text>
                  </View>
                  
                </View>

                <View style={{ flexDirection: 'row', alignItems:'center', justifyContent:'center', marginTop: Scale(sendByState.icon ? 8 : 0), marginHorizontal: Scale(sendByState.icon ? 8 : 0) }}>
                  {sendByState.icon && <View style={{ flex: 0.2, alignItems: 'center', marginRight: Scale(8)}}>
                  <Image
                      style={{ height: sendByState.height, width: sendByState.width }}
                      source={getIcon(sendByState.icon)}
                      resizeMode='stretch' />
                  </View>}
                    <View style={{ flex: 1, justifyContent:'center' }}>
                      {<Text style={{ color: Colors.black, fontWeight: '200' }}>{dataDetil?.senders_methode}</Text>}
                    </View>
                </View>

               
              </View>
            </View>

            <View style={{ paddingHorizontal: Scale(16), paddingVertical: Scale(16), borderColor: Colors.gray, borderBottomWidth: Scale(2) }}>
           
              <View style={{}}>
                <View style={{ flexDirection: 'row' }}>
                  <View style={{ flex: 1 }}>
                    <Text style={{ color: Colors.black, fontWeight: '600' }}>{"Pilihan Pembayaran"}</Text>
                  </View>
                  
                </View>

                <View style={{ flexDirection: 'row', alignItems:'center', justifyContent:'center', marginTop: Scale(paymentMethode.icon ? 8 : 0), marginHorizontal: Scale(paymentMethode.icon ? 8 : 0) }}>
                  {paymentMethode.icon && <View style={{ flex: 0.2, alignItems: 'center', marginRight: Scale(8)}}>
                  <Image
                      style={{ height: paymentMethode.height, width: paymentMethode.width }}
                      source={getIcon(paymentMethode.icon)}
                      resizeMode='contain' />
                  </View>}
                    <View style={{ flex: 1, justifyContent:'center' }}>
                      {<Text style={{ color: Colors.black, fontWeight: '200' }}>{dataDetil?.payment_methode}</Text>}
                    </View>
                </View>

               
              </View>
            </View>

           

           

            <View style={{ paddingHorizontal: Scale(16), paddingVertical: Scale(16), borderColor: Colors.gray, borderBottomWidth: Scale(2) }}>

              <View style={{ flexDirection: 'row' }}>
                <View style={{ flex: 1 }}>
                  <Text style={{ color: Colors.black, fontWeight: '600' }}>{"Total Harga Pesanan"}  </Text>
                </View>

              </View>

              <View style={{ paddingVertical: Scale(4) }}>
                <Text style={{ color: Colors.black, fontWeight: '300' }}>{dataDetil?.order_total}</Text>
              </View>
            </View>

            {route.params?.item.status === "orders_ready" && <View style={{marginHorizontal: Scale(16), marginVertical: Scale(16)}}>
              <Buttons
                onPress={() => setShowModalConfirm(true)}
                switchAccount={true}
                title={("Kirim")} />

              <Buttons
                style={[{ backgroundColor: Colors.white, borderColor: Colors.primaryColorHub, borderWidth: Scale(1) }]}
                styleTitle={{ color: Colors.primaryColorHub }}
                onPress={() => console.log("")}
                switchAccount={true}
                title={("Batalkan Pesanan")} />
            </View>}

            <ModalConformationSendHub
              data={dataDetil}
              onPresButtonConfirm={(value) => onPresHubSendConfirm()}
              onCloses={() => setShowModalConfirm(false)}
              ShowComment={showModalConfirm}
              loading={(value) => setLoading(value)}
              cekError={(value1, value2) => cekError(value1, value2)}
            />

            <Loading
              visible={loading} />

            <PopUp
              visible={warning}
              onPressButton={() => { actionButton() }}
              title={contentWarning?.title}
              desc={contentWarning?.desc}
              titleButton={contentWarning?.titleButton} />
          </View>
        </ScrollView>
        
      </View>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  button: {
    alignItems: 'center',
    backgroundColor: '#DDDDDD',
    padding: 10,
    width: 300,
    marginTop: 16,
  },
});
